const items = input.rows;
const totalRevenue = items.reduce((sum, i) => sum + (i.total_revenue || 0), 0);
const totalUnits = items.reduce((sum, i) => sum + (i.units_sold || 0), 0);
const avgPopularity = totalUnits / Math.max(items.length, 1);
const avgMargin = items.reduce((sum, i) => sum + ((i.price - i.food_cost) / Math.max(i.price, 0.01)), 0) / Math.max(items.length, 1);

const analyzed = items.map(item => {
  const margin = item.price > 0 ? (item.price - item.food_cost) / item.price : 0;
  const foodCostPct = item.price > 0 ? (item.food_cost / item.price) * 100 : 0;
  const isPopular = (item.units_sold || 0) >= avgPopularity;
  const isProfitable = margin >= avgMargin;
  let classification;
  if (isPopular && isProfitable) classification = 'Star';
  else if (isPopular && !isProfitable) classification = 'Plow Horse';
  else if (!isPopular && isProfitable) classification = 'Puzzle';
  else classification = 'Dog';
  return { ...item, contributionMargin: margin, foodCostPercentage: foodCostPct, classification, revenueShare: totalRevenue > 0 ? ((item.total_revenue || 0) / totalRevenue * 100) : 0 };
});

return { items: analyzed, summary: { totalRevenue, totalUnits, itemCount: items.length, avgMargin: (avgMargin * 100), stars: analyzed.filter(i => i.classification === 'Star').length, dogs: analyzed.filter(i => i.classification === 'Dog').length } };

config.prompt:
You are a restaurant consultant specializing in menu engineering.

Weekly Performance Summary:
- Total Revenue: ${{summary.totalRevenue}}
- Total Units Sold: {{summary.totalUnits}}
- Active Menu Items: {{summary.itemCount}}
- Stars (high popularity + high margin): {{summary.stars}}
- Dogs (low popularity + low margin): {{summary.dogs}}

Detailed Item Analysis:
{{#each items}}{{this.item_name}} | Category: {{this.category}} | Price: ${{this.price}} | Food Cost: ${{this.food_cost}} | Units Sold: {{this.units_sold}} | Revenue: ${{this.total_revenue}} | Margin: {{this.contributionMargin}}% | Classification: {{this.classification}} | Avg Rating: {{this.avg_rating}}
{{/each}}

Provide:
1. Top 3 actionable recommendations for menu optimization
2. Items to consider removing or repricing (Dogs with low ratings)
3. Items with upsell potential (Puzzles with high margins)
4. Suggested new item categories based on gaps
5. Food cost alerts (items with food cost percentage above 35%)

Be specific with numbers and item names. Keep recommendations practical for a restaurant operator.
